   337→		TranscriptLinesAtStart: opts.TranscriptLinesAtStart,
   338→		TokenUsage:             opts.TokenUsage,
   339→	}
   340→
   341→	// Merge with existing metadata if present (multi-session checkpoint)
   342→	if existingMetadata != nil {
   343→		// Get existing session count (default to 1 for backwards compat)
   344→		existingCount := existingMetadata.SessionCount
   345→		if existingCount == 0 {
   346→			existingCount = 1
   347→		}
   348→		metadata.SessionCount = existingCount + 1
